#include "SubtitleBox.hpp"
#include "Settings.hpp"
#include "TextUtil.hpp"

using namespace geode::prelude;

namespace taf {
    namespace {
        // Font generated by Geode from DejaVu Sans Bold (Latin + Hebrew), see mod.json.
        std::string subtitleFont() {
            auto font = Mod::get()->expandSpriteName("subFont.fnt");
            // If the generated font is missing for any reason, fall back to GD's font.
            if (!CCFileUtils::sharedFileUtils()->isFileExist(
                    CCFileUtils::sharedFileUtils()->fullPathForFilename(font.c_str(), false))) {
                return "bigFont.fnt";
            }
            return font;
        }
        constexpr ccColor3B SUB_TOP = {255, 236, 90};    // warm yellow
        constexpr ccColor3B SUB_BOTTOM = {255, 150, 40}; // orange
    }

    SubtitleBox* SubtitleBox::create(float width) {
        auto ret = new SubtitleBox();
        if (ret->init(width)) {
            ret->autorelease();
            return ret;
        }
        delete ret;
        return nullptr;
    }

    bool SubtitleBox::init(float width) {
        if (!CCNodeRGBA::init()) return false;
        m_width = width;
        this->setAnchorPoint({0.5f, 0.5f});
        this->setCascadeOpacityEnabled(true);

        m_bg = CCScale9Sprite::create("square02_small.png");
        m_bg->setColor({0, 0, 0});
        m_bg->setOpacity(140);
        this->addChild(m_bg, 0);

        m_name = CCLabelBMFont::create("", "goldFont.fnt");
        m_name->setAnchorPoint({0.5f, 0.f});
        this->addChild(m_name, 2);

        m_lines = CCNodeRGBA::create();
        m_lines->setCascadeOpacityEnabled(true);
        this->addChild(m_lines, 1);

        m_bg->setCascadeOpacityEnabled(true);
        this->setVisible(false);
        return true;
    }

    void SubtitleBox::show(std::string const& speaker, ccColor3B color, std::string const& text) {
        bool changed = !m_shown || speaker != m_speaker || text != m_text;
        m_speaker = speaker;
        m_text = text;
        m_color = color;
        if (!changed) return;

        this->layout();
        this->setVisible(true);
        this->stopAllActions();
        if (!m_shown) {
            this->setOpacity(0);
            this->setScale(0.96f);
        }
        this->runAction(CCSpawn::create(
            CCFadeTo::create(0.12f, 255),
            CCEaseBackOut::create(CCScaleTo::create(0.18f, 1.f)),
            nullptr
        ));
        m_shown = true;
    }

    void SubtitleBox::hide() {
        if (!m_shown) return;
        m_shown = false;
        m_text.clear();
        this->stopAllActions();
        this->runAction(CCSequence::create(
            CCFadeTo::create(0.15f, 0),
            CCHide::create(),
            nullptr
        ));
    }

    void SubtitleBox::applySettings() {
        if (m_shown) this->layout();
    }

    void SubtitleBox::layout() {
        m_lines->removeAllChildren();
        float scale = 0.55f * settings::subtitleSize();
        std::string text = settings::uppercase() ? text::upperAscii(m_text) : m_text;
        auto font = subtitleFont();

        auto measurer = CCLabelBMFont::create("", font.c_str());
        auto measure = [&](std::string const& s) {
            measurer->setString(s.c_str());
            return measurer->getContentSize().width * scale;
        };
        float maxWidth = m_width - 30.f;
        auto lines = text::wrap(text, maxWidth, measure);
        if (lines.size() > 4) lines.resize(4);

        float lineH = 0.f;
        std::vector<CCLabelBMFont*> labels;
        for (auto const& l : lines) {
            auto lbl = CCLabelBMFont::create(text::toVisual(l).c_str(), font.c_str());
            lbl->setScale(scale);
            if (lbl->getScaledContentSize().width > maxWidth) {
                lbl->setScale(scale * maxWidth / lbl->getScaledContentSize().width);
            }
            lineH = std::max(lineH, lbl->getContentSize().height * scale * 0.86f);
            labels.push_back(lbl);
        }

        float textH = lineH * labels.size();
        float y = textH / 2.f - lineH / 2.f;
        int i = 0;
        for (auto lbl : labels) {
            // simple vertical gradient across lines, like the video's titles
            float t = labels.size() > 1 ? static_cast<float>(i) / (labels.size() - 1) : 0.f;
            lbl->setColor({
                static_cast<GLubyte>(SUB_TOP.r + (SUB_BOTTOM.r - SUB_TOP.r) * t),
                static_cast<GLubyte>(SUB_TOP.g + (SUB_BOTTOM.g - SUB_TOP.g) * t),
                static_cast<GLubyte>(SUB_TOP.b + (SUB_BOTTOM.b - SUB_TOP.b) * t),
            });
            lbl->setCascadeOpacityEnabled(true);
            lbl->setPosition({0.f, y});
            m_lines->addChild(lbl);
            y -= lineH;
            ++i;
        }

        float boxH = textH + 18.f;
        m_bg->setContentSize({m_width, boxH});
        m_bg->setPosition({0.f, 0.f});

        m_name->setString(m_speaker.c_str());
        m_name->setScale(0.5f);
        m_name->setColor(m_color);
        m_name->setPosition({-m_width / 2.f + 14.f + m_name->getScaledContentSize().width / 2.f, boxH / 2.f - 2.f});
        m_name->setVisible(!m_speaker.empty());
    }
}
